import{_ as d,o as r,c as a,a6 as e}from"./chunks/framework.QQy01QNh.js";const b=JSON.parse('{"title":"第十三部分　接口与工具","description":"","frontmatter":{"title":"第十三部分　接口与工具"},"headers":[],"relativePath":"theory/part-13.md","filePath":"theory/part-13.md"}'),o={name:"theory/part-13.md"};function h(n,t,i,p,s,l){return r(),a("div",null,[...t[0]||(t[0]=[e('<div class="theory-source"><p><a id="part_13"></a></p><h1 id="part-title-13" tabindex="-1">第十三部分　接口与工具 <a class="header-anchor" href="#part-title-13" aria-label="Permalink to &quot;第十三部分　接口与工具 {#part-title-13}&quot;">​</a></h1><p>本部分把此前十二部分定义的对象、命题、尺度、机制、行动者、多圈层联合状态和动态推演要求转换为可观察、可质疑、可复核、可撤回的有限判断。它不新增世界事实，也不把表格完整度当作事实成立。进入工具流前，必须已有 D0 候选对象记录和九轴尺度记录；对象、边界、尺度、时间窗、同一性判据或用途改变时，已有判断不得平移沿用。</p><p>工具流程采用两级结构：七闸是唯一主流程，五闸十三步是诊断展开层。七闸回答判断能否进入下一层；五闸十三步在复杂案例中展开需要提交的材料，但不另行出具与七闸竞争的“通过”结论，也不产生第二套流程状态。</p><p>最重要的边界是：工具层不产生授权。流程、证据、强判断八件套全部完成，也只产生描述、候选机制、比较判断、强判断候选或行动要求。现实行动仍须另经结构化选择记录、C12 十组件桥、同一条有效 J 原子授权以及 O1-O4；工具输出不能替代其中任何一项。</p><p>以下流程管理以本框架形成的结构化判断及其移交。阅读、原文校对或低影响的问题澄清，可以采用与任务相称的简明记录；不能因为没有运行全部工具流，就宣布已有领域事实不存在。进入正式诊断、前瞻或高影响用途时，则必须满足相应完整合同，不能靠更换输出名称降低责任。</p><h2 id="section-13-1" tabindex="-1">13.1　四次转换 <a class="header-anchor" href="#section-13-1" aria-label="Permalink to &quot;13.1　四次转换 {#section-13-1}&quot;">​</a></h2><p>四次转换不是把理论词换成现实标签，而是逐次增加记录责任。任一步失败，依赖该步的输出停在该步之前，不能靠后一步的格式完整补救；其他独立判断按自己的依据和用途分别审查。</p><table tabindex="0"><thead><tr><th>ID</th><th>转换</th><th>必须得到什么</th><th>失败时停在哪里</th></tr></thead><tbody><tr><td>IT1</td><td>结构变量到可观察信号</td><td>对象、尺度、观察位置、时间窗、测量协议和缺失状态明确的信号记录</td><td>概念映射或材料缺口</td></tr><tr><td>IT2</td><td>可观察信号到证据强度</td><td>来源、观察、比较条件、覆盖、反例、替代解释和不确定性分开的证据记录</td><td>未分级材料或待检验假设</td></tr><tr><td>IT3</td><td>证据强度到判断等级</td><td>有命题合同、适用边界、反向条件、证伪条件和撤回条件的判断</td><td>候选解释或观察意见</td></tr><tr><td>IT4</td><td>判断等级到行动要求与上限</td><td>受影响位置、保护底板、禁止动作、停止、申诉、回滚及尚缺 N/J/O/C12 的清单</td><td>描述、补证或不行动要求</td></tr></tbody></table><p>IT1 防止把结构叙事当成观察事实；IT2 防止把出处、材料或表态直接当成证据；IT3 防止把相关、类比或单一机制故事升级为结论；IT4 防止从事实判断直接跳到处置。四次转换全部通过也不改变授权状态。</p><p>任何 IT 转换失败，依赖该转换的后续转换只能记 not_run，并停止或降低其所支持的命题、比较判断、强判断候选和行动要求。共享同一缺口的下游结论不得通过改名、拆分或另开分支恢复上限；后续 not_run 只保留该失败链，八件套齐全也不能补回断口。对于不依赖失败环节、具有独立依据且用途满足自身要求的判断，可以保留其原有地位。若缺口触及全局来源身份、共同事实前提、对象边界或整项任务的合法使用条件，则全部依赖输出一并停止或降档。高影响采用所需门禁失败时，同一判断不得仅通过改称普通意见而保留原用途。</p><h2 id="section-13-2" tabindex="-1">13.2　通用原语与人类变量接口(11+11)的调用方式 <a class="header-anchor" href="#section-13-2" aria-label="Permalink to &quot;13.2　通用原语与人类变量接口(11+11)的调用方式 {#section-13-2}&quot;">​</a></h2><p>第七部分的 HV01-HV11 是人类结构化世界的十一项接口；第三部分的 U01-U11 是通用结构原语。工具层可以在同一案例中并列调用二者，但不把编号相同、数量相同或问题相似解释为一一等价。</p><p>调用时至少登记：通用或人类接口 ID、有效对象、九轴尺度、所选支持路由、实例证据、替代解释、缺失状态、判断上限与行动上限。H1/H4/H5 只能经各自 H-instance 进入指定路由；G1-G4 只能经结果前冻结的 G-instance 支持经验主张。接口卡能提出问题，却不能因字段填满而证明对象事实。</p><h2 id="section-13-3" tabindex="-1">13.3　七闸：唯一主流程 <a class="header-anchor" href="#section-13-3" aria-label="Permalink to &quot;13.3　七闸：唯一主流程 {#section-13-3}&quot;">​</a></h2><p>七闸按具体命题及其依赖顺序运行。某一闸失败后，依赖它的后续闸只能记 not_run，相应判断与行动要求停止或降档；后续 not_run 不能抬高失败闸已经压低的上限，也不能一边承认对象或证据未过闸，一边让相关后续程序自报通过。不依赖失败环节的判断须保留独立证据与用途审查，不得以另一命题的通过掩盖本命题失败。全局来源身份、共同事实前提、对象边界或任务合法使用条件失效时，全部依赖输出一起停止。对象、证据版本、受影响位置或用途发生实质变化时，从最早受影响的闸重新运行。</p><table tabindex="0"><thead><tr><th>ID</th><th>闸门</th><th>核心问题</th><th>未通过时的输出上限</th></tr></thead><tbody><tr><td>IG1</td><td>有效对象闸</td><td>对象、边界、九轴尺度、时间窗与 K 是否支持本次判断？</td><td>重新界定对象、尺度未知或对象转换复核</td></tr><tr><td>IG2</td><td>证据追踪闸</td><td>来源、材料、观察、证据、反例、案例与判断是否分开可回溯？</td><td>材料整理、候选问题或待检验假设</td></tr><tr><td>IG3</td><td>受影响位置闸</td><td>哪些直接、间接、二阶、跨域与跨期位置会改变处境？</td><td>补充影响核算；暂停强判断和高影响用途</td></tr><tr><td>IG4</td><td>权力与反报复闸</td><td>低权力位置能否安全补证、反驳、拒绝、停止和申诉？</td><td>不得因沉默作不利推断；降低发布与判断档位</td></tr><tr><td>IG5</td><td>中介与反身性闸</td><td>指标、平台、AI、公开评价或诊断行为是否改变证据和对象？</td><td>高反身性未收束；改写为条件状态转移</td></tr><tr><td>IG6</td><td>强判断程序闸</td><td>按用途与可预见影响触发强判断的命题是否完整提交 SJ1-SJ8？公开传播须提高审查，但不单独触发全部分析升为强判断。</td><td>相关强判断与高影响用途停止；独立成立且用途合规的比较判断分别审查</td></tr><tr><td>IG7</td><td>行动上限闸</td><td>最多只能提出什么要求，哪些动作禁止，何时停止、申诉和回滚？</td><td>描述、证据缺口、不行动或继续审议</td></tr></tbody></table><p>七闸全过不表示结论为真，只表示相应记录门没有缺口。经验命题仍由其命题合同和实例证据判定；规范目标仍需明示 N 前提；现实行动仍需选择、C12、J 与 O 程序。特别是 IG7 只能记录外部规范层与授权层是否具备，不能由工具流自己写成“已授权”。</p><p>IG6 有一条专门适用性规则：普通 L1/L2 输出可以把它记为 not_applicable，但必须写明为什么本次不触发强判断程序，且这不会阻断 IG7；一旦 IG6 记为 passed，同一运行记录必须绑定完整、逐项 passed 的 SJ1—SJ8。用“已检查”字符串或空理由不能代替八项结果。</p><h2 id="section-13-4" tabindex="-1">13.4　五闸十三步：诊断展开层 <a class="header-anchor" href="#section-13-4" aria-label="Permalink to &quot;13.4　五闸十三步：诊断展开层 {#section-13-4}&quot;">​</a></h2><p>当对象复杂、高责任、高反身性，或七闸需要展开取证时，运行五闸十三步。五闸是展开过程的局部检查，不生成第二套主流程状态。</p><table tabindex="0"><thead><tr><th>ID</th><th>展开闸</th><th>必须展开的材料</th><th>对应主闸</th></tr></thead><tbody><tr><td>FG1</td><td>对象闸</td><td>对象、边界、尺度、时间窗</td><td>IG1</td></tr><tr><td>FG2</td><td>证据闸</td><td>信号成本、来源、权重、复核</td><td>IG2</td></tr><tr><td>FG3</td><td>尺度闸</td><td>九轴尺度、尺度内对象与证据、尺度变化</td><td>IG1、IG2</td></tr><tr><td>FG4</td><td>责任闸</td><td>权利/资源影响、反向条件、修复窗口、申诉复核</td><td>IG3、IG4、IG6</td></tr><tr><td>FG5</td><td>观测闸</td><td>观察前基线、观察中反应、发布后反应、递归封顶</td><td>IG5</td></tr></tbody></table><p>十三步按现实问题到写回的顺序形成一条可审计工作链：</p><table tabindex="0"><thead><tr><th>ID</th><th>步骤</th><th>最小产物</th></tr></thead><tbody><tr><td>DS01</td><td>问题入口</td><td>不使用框架术语的现实问题、请求者和用途</td></tr><tr><td>DS02</td><td>对象与边界</td><td>有效对象、子系统、上级环境和外部通道</td></tr><tr><td>DS03</td><td>信号分层</td><td>事实、行为、资源、反馈、叙事、感受、推测和噪声分栏</td></tr><tr><td>DS04</td><td>观测参与登记</td><td>被观察知情、观察者权力、发布影响和候选反应</td></tr><tr><td>DS05</td><td>主导约束</td><td>候选约束、所选约束、选择证据和竞争约束</td></tr><tr><td>DS06</td><td>状态与窗口</td><td>适用对象的 S0-S6 原型引用、状态内位置、并行子系统和反向条件；不适用时说明原因，保留领域自身的状态与窗口</td></tr><tr><td>DS07</td><td>核心结构扫描</td><td>锚点、承接层、传导链、边界和反馈写回</td></tr><tr><td>DS08</td><td>关键保护变量</td><td>受保护变量、受损路径、资源、冗余和修复/回流路径</td></tr><tr><td>DS09</td><td>承接与偿付</td><td>成本承担者、回流获得者、停止权、长期透支与损害转移</td></tr><tr><td>DS10</td><td>隐患与边界类型</td><td>维护债、快慢错配、指标替代、摘要失真和对象转换候选</td></tr><tr><td>DS11</td><td>机制候选</td><td>材料允许且足以改变判断的竞争机制、各自所需证据、削弱证据和淘汰规则；没有合理竞争解释时，说明检索范围与失败条件，不为数量要求虚构机制</td></tr><tr><td>DS12</td><td>分支预判</td><td>触发、早期信号、反向条件、修复窗口和最低行动要求</td></tr><tr><td>DS13</td><td>输出与写回</td><td>现实语言输出、修改触发器、记录范围、复核、撤回和回滚</td></tr></tbody></table><p>DS06 涉及 S0-S6 时，只能用于适用的人类意向性集体，不适用对象不得强套；不能把 S0-S6 写成成熟度或命运。DS08 发现重要保护变量，只能生成保护需求；DS09 发现承接或透支，不能生成牺牲义务或完整责任；DS11 的机制候选不得跨过因果合同；DS12 的分支不是确定未来；DS13 没有复核和撤回时，不得把判断写入组织记录、资格、分配或公共记忆。</p><h2 id="section-13-5" tabindex="-1">13.5　强判断八件套 <a class="header-anchor" href="#section-13-5" aria-label="Permalink to &quot;13.5　强判断八件套 {#section-13-5}&quot;">​</a></h2><p>强判断按判断的用途与可预见影响界定，不按语气、篇幅或表达自信程度界定。拟用于或可合理预见被用于处置、资格、权利、资源分配，或对具体主体的声誉与公共记忆产生实质影响的判断，以及被嵌入自动化、组织化、制度化决定的判断，进入强判断程序。中间评分、建议或材料筛选通过后续环节影响这些决定时，同样核查其实际用途。公开传播是提高审查要求的因素，应结合被评价对象、事实指控、可识别性、传播范围和后果判断，不单独作为所有分析输出升级为强判断的充分条件。普通论证评价、机制解释或规范意见，在不触及上述用途与影响时，可以按与其任务相称的证据和复核要求提出明确结论。自称评论、研究或草案不能豁免实际达到强判断条件的输出。只有 L3 且七闸全过、下列八项逐项通过时，才可登记强判断候选；它仍不产生现实行动授权。</p><table tabindex="0"><thead><tr><th>ID</th><th>组件</th><th>必须回答什么</th></tr></thead><tbody><tr><td>SJ1</td><td>反向条件</td><td>出现什么情况会削弱、反转或撤回判断？</td></tr><tr><td>SJ2</td><td>修复窗口</td><td>窗口何在、根据何在、何时失效？</td></tr><tr><td>SJ3</td><td>证据要求</td><td>支持、缺失和反向证据分别是什么？</td></tr><tr><td>SJ4</td><td>申诉入口</td><td>谁可进入、谁负责、时限多长、能否改变结果？</td></tr><tr><td>SJ5</td><td>反报复保护</td><td>哪些行为受保护、如何监测、如何独立报告和补救？</td></tr><tr><td>SJ6</td><td>证据补充权</td><td>如何补证、纠正版本并同步下游？</td></tr><tr><td>SJ7</td><td>外部复核触发</td><td>何时触发、谁独立复核、能否访问材料和停止结果？</td></tr><tr><td>SJ8</td><td>回滚与写回</td><td>回到哪个状态、谁修复、哪个版本权威、如何同步？</td></tr></tbody></table><p>任何一项缺失，针对该强判断的 IG6 失败，该判断不得进入强判断候选或保留原高影响用途；只能在与其材料和实际用途相称的范围内登记内部假设、开放断言或候选机制。不依赖该缺项、具有独立依据且不触发强判断用途的 L2 比较判断，可以保留；共同前提失效仍阻断全部依赖判断，不得靠改名或拆分规避。申诉入口若不能改变记录或行动，不算有效申诉；外部名义不等于独立；声明、道歉或新版本发布不等于实际回滚和修复。</p><h2 id="section-13-6" tabindex="-1">13.6　诊断档位 <a class="header-anchor" href="#section-13-6" aria-label="Permalink to &quot;13.6　诊断档位 {#section-13-6}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>档位</th><th>适用</th><th>输出上限</th></tr></thead><tbody><tr><td>L1</td><td>轻量描述与试探问题</td><td>低复杂、低影响、可逆且信息有限</td><td>描述、问题和下一观察</td></tr><tr><td>L2</td><td>标准可复核判断</td><td>需要结构比较但不进入高责任处置</td><td>有边界的比较判断或机制候选</td></tr><tr><td>L3</td><td>高责任强判断候选</td><td>实质高影响、嵌入自动化或组织化或制度化决定的判断；公开传播按对象、事实指控、可识别性和后果审查</td><td>七闸与八件套通过后的强判断候选</td></tr></tbody></table><p>档位升高不是“更接近真理”，而是增加记录责任。证据覆盖下降、对象转换、反身性失控、申诉或反报复失效时必须降级。紧急也不能删除对象、保护或停止条件；等待代价高时，只能在相应授权外另提出最窄、可撤回、可监测的行动要求。</p><h2 id="section-13-7" tabindex="-1">13.7　六项正式工具 <a class="header-anchor" href="#section-13-7" aria-label="Permalink to &quot;13.7　六项正式工具 {#section-13-7}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>工具</th><th>作用与边界</th></tr></thead><tbody><tr><td>TOOL-EVIDENCE-LEDGER</td><td>来源—证据台账</td><td>分离来源、材料、观察、证据、反例、覆盖和不确定性；不证明命题</td></tr><tr><td>TOOL-OPEN-ASSERTION</td><td>开放断言记录</td><td>留下可质疑、可证伪、可撤回的临时判断靶点；不用作高责任处置</td></tr><tr><td>TOOL-CLAIM-VALIDATION</td><td>命题验证表</td><td>对命题类型、证据、反证、证伪条件、影响与上限逐项登记</td></tr><tr><td>TOOL-FORECAST-REGISTRY</td><td>前瞻登记</td><td>冻结预测、窗口、触发、早期信号、反向信号和修改目标</td></tr><tr><td>TOOL-STRESS-TEST</td><td>反例与尺度压力测试</td><td>用边界案例、对抗解释和尺度变化找失败位置并收缩范围</td></tr><tr><td>TOOL-AI-BOUNDARY</td><td>AI 输出边界</td><td>强制来源披露、缺失材料、人类责任人、不确定性、禁止用途和复核撤回</td></tr></tbody></table><p>证据台账不能把“有来源”写成“被支持”；开放断言不能代替命题验证；预测失败必须写回相关命题；内部压力测试只是一场风洞，不是外部经验支持。工具之间可以引用记录 ID，但不得互相循环自证。</p><p>自动校验适合核对封闭字段、引用是否可解析、版本和状态是否一致、计算能否复算。它不能替代材料鉴别、受影响者证言、因果识别或价值选择。应让程序承担可机械完成的工作，让读者能够审查真正的判断理由；完整日志与清楚正文可以分开保存并相互定位。</p><h2 id="section-13-8" tabindex="-1">13.8　AI 使用边界 <a class="header-anchor" href="#section-13-8" aria-label="Permalink to &quot;13.8　AI 使用边界 {#section-13-8}&quot;">​</a></h2><p>AI 可以整理材料、检查字段、比较版本、生成候选问题、列出替代解释和发现格式矛盾，也应在证据和规范前提允许时比较机制、形成可反驳判断、推荐方案并起草完整制度、计划和评论。AI 不得虚构来源、把训练记忆当作当前证据、替当事人表达同意、把沉默解释为同意、代替决策主体或授权机关、隐藏不确定性，也不得独立作出高风险现实决定。</p><p>AI 输出必须说明：使用了哪些材料、缺什么、哪些内容是观察/推断/类比、谁承担最终判断责任、允许怎样使用、何时复核和撤回。涉及身份暴露、报复风险或正当不透明时，保护性省略必须与“没有证据”保持可区分。</p><p>AI 的使用责任还应按实际分工落到材料提供者、目标与权限决定者、系统维护者、执行者和复核者。承担技术步骤的设施与程序不会仅因输出建议或执行指令而成为能够承担道德或法律责任的主体；依法具有特定责任能力的组织，则依据其制度身份与具体事项分别判断。自动化程度提高也不把全部责任压给最后点击的人。复核者必须有足够材料、时间、能力和真正可生效的停止权限，组织还须为这些条件提供资源。</p><h2 id="section-13-9" tabindex="-1">13.9　运行记录与失败语义 <a class="header-anchor" href="#section-13-9" aria-label="Permalink to &quot;13.9　运行记录与失败语义 {#section-13-9}&quot;">​</a></h2><p>每次工具运行生成一个字段闭合的 flow_execution_record。它登记对象和尺度记录、L1-L3 档位、IT1-IT4 结果、IG1-IG7 结果、是否运行五闸十三步、是否触发 SJ1-SJ8、证据、替代解释、不确定性、输出类别、判断/行动上限、规范移交、申诉、回滚和状态。</p><p>行动上限使用封闭输出上限格：description_only、diagnostic_only、requirements_only。每一档都固定可出现的输出类别，并且 can_authorize=false、can_execute=false；调用者不能在自由文本中自报“已经授权”，也不能自行扩展允许类别。action_requirements 只是对外部选择与授权程序提出所需条件，不是可执行命令。</p><p>规范移交须链接可核查的外部选择、C12 与授权记录，或明示它们尚未具备。引用须标明对象、动作、范围、时间与实际核验依据；模糊标签、自报已通过或同一记录循环引用都不能证明权限。具体引用格式由实现确定，不改变工具不得自行签发授权的边界。</p><p>结果状态要保持可区分：passed 表示该项记录门通过，failed 表示已运行但失败，not_run 表示因前闸或范围限制没有运行；unknown、not_applicable、not_observable 与 withheld_for_protection 仍是四种不同缺失状态。失败不能改写成不适用，保护性隐匿不能改写成不存在。</p><p>运行记录的 authorization_effect 恒为 none。即使规范选择、C12、J 和 O 的外部引用均已存在，本记录也只是核对和移交它们，不自行铸造授权。所有已复核输出必须保留可达申诉与实际撤回/纠正路径；不能撤回的工具结论不得进入高影响难逆用途。</p><h2 id="section-13-10" tabindex="-1">13.10　多圈层推演九闸 <a class="header-anchor" href="#section-13-10" aria-label="Permalink to &quot;13.10　多圈层推演九闸 {#section-13-10}&quot;">​</a></h2><p>七闸是解释与诊断的唯一主流程；当任务明确要求动态推演、条件前瞻或有限选择时，在其基础上展开九闸。九闸不得绕过七闸已经规定的对象、证据、受影响位置、权力、反身性、强判断程序和行动上限。</p><table tabindex="0"><thead><tr><th>闸</th><th>核心检查</th><th>失败输出</th></tr></thead><tbody><tr><td>DF1 事实冻结</td><td>事件类型、来源、时间、证据截止和争议</td><td>事实问题清单</td></tr><tr><td>DF2 联合对象</td><td>行动者、圈层、关系、成员与 K</td><td>候选分组或单焦点退回</td></tr><tr><td>DF3 双通道与时钟</td><td>与任务相关的物质/体验—意义条件、时钟、未知；无关项带理由不适用</td><td>保留状态快照；暂停依赖缺失条件的传播，独立路径分别审查</td></tr><tr><td>DF4 机制传播</td><td>通道、阈值、时延、反馈和级联</td><td>候选机制与区分观察</td></tr><tr><td>DF5 路径分叉</td><td>条件、父子节点、早期与反向信号</td><td>并行路径，不强制排序</td></tr><tr><td>DF6 前瞻登记</td><td>目标、期限、简单基线、校准和回写</td><td>仅情景推演</td></tr><tr><td>DF7 规范选择</td><td>N、PF、受影响者、方案与不行动</td><td>缺失所阻断的推荐暂停；保留独立成立的评价、明示前提的条件建议与补证需求，不产生执行权限</td></tr><tr><td>DF8 授权与执行</td><td>J、O、责任、停止、回滚和补救</td><td>外部移交，不执行</td></tr><tr><td>DF9 结果回写</td><td>结果、基线比较、偏差、降级和退役</td><td>保留失败并开新版本</td></tr></tbody></table><p>工具在 DF2 可以提出圈层候选，在 DF5 可以提出变量候选，但任何候选都保持 candidate。DF6 未通过时，输出不能使用“将会”“预计命中”等前瞻语气；DF7 或 DF8 未通过时，输出不能给出可执行指令。DF9 不允许覆盖原运行。</p><h2 id="section-13-11" tabindex="-1">13.11　AI 在动态运行中的边界 <a class="header-anchor" href="#section-13-11" aria-label="Permalink to &quot;13.11　AI 在动态运行中的边界 {#section-13-11}&quot;">​</a></h2><p>AI可以整理材料、核对可定位原文、发现字段缺口、生成和比较竞争路径、检查合同一致性和计算已登记指标，并在明示规范前提下形成有依据的局部判断、建议和完整文本。AI不能仅凭自身生成、自述或内部流程认证现实事件，不能诊断人格、替当事人披露信息、凭自己的分类决定对他人有约束力的圈层边界、把模拟当事实、替他者确定争议价值前提或签发授权。外部材料是否支持具体事实，按材料身份、方法、反例和拟定用途分别判断；原文忠实也不自动证明原文所述现实为真。对AI自动提出的变量，系统必须记录其模型候选身份、最小检验和禁止用途，没有相应外部证据前不得升级。</p><h3 id="section-13-11-1" tabindex="-1">13.11.1 AI材料核对与工具行动链 <a class="header-anchor" href="#section-13-11-1" aria-label="Permalink to &quot;13.11.1 AI材料核对与工具行动链 {#section-13-11-1}&quot;">​</a></h3><p>核对生成答案时，分开检查出处是否存在、引用信息是否正确、原段是否支持该句，以及该句所述世界事实是否有足够依据。给定来源没有提到，不等于该句一定错误；忠实转述一个错误来源，也不等于已经查明事实。缺少公开网页的地方知识、口述和保护性材料，应保留合适的核验路径及公开范围，不能直接当作不存在。</p><p>检索增强可以改善资料取得与任务表现，一致性或不确定性检测也可能发现某类错误；它们的作用仍受检索覆盖、共同来源和错误类型限制。稳定重复的错误可以显得一致，多个模型复述同一失实材料也不构成多份独立证据。形式检查器能够确认明示前提下的推导，同时不能替这些前提在现实中的成立作证。</p><p>自动化行动应分别记录建议、工具请求、应用执行、外部状态与后果。模型写出“已停止”不证明执行器收到停止指令，界面显示“已删除”不证明下游副本已消失，人工改过建议也不证明该改变赶在不可逆动作之前生效。用于实际保护和纠错的权限，必须在对应系统中可以行使。</p><h3 id="section-13-11-2" tabindex="-1">13.11.2　任务终点与可核执行链 <a class="header-anchor" href="#section-13-11-2" aria-label="Permalink to &quot;13.11.2　任务终点与可核执行链 {#section-13-11-2}&quot;">​</a></h3><p>工具链的核验终点由用户请求或制度任务确定。只要求生成草案时，正确保存、可打开且内容满足要求可以构成该次交付；要求改变外部记录时，工具返回成功还须由对应外部对象的状态证实；要求实际补救时，又须核对资源、权利或服务到达。较窄终点真实完成，不必等待全部生活后果才承认；较宽终点也不能被前端成功回执代替。</p><table tabindex="0"><thead><tr><th>环节</th><th>最小核验对象</th><th>典型断点</th></tr></thead><tbody><tr><td>建议形成</td><td>目标、材料、拟改对象与允许范围</td><td>把生成文本当作已采用</td></tr><tr><td>工具请求</td><td>具体动作、参数、当前对象版本与权限</td><td>正确建议发向错误对象</td></tr><tr><td>应用执行</td><td>请求是否被接收、执行或拒绝，重复请求如何处理</td><td>请求送达但排队、失败或重复执行</td></tr><tr><td>外部状态</td><td>目标对象与依赖对象是否发生预期变化</td><td>本地标记改变但实际执行仍读旧状态</td></tr><tr><td>任务后果</td><td>指定受益或保护终点与残余问题</td><td>更正记录已生效但错过的机会未恢复</td></tr></tbody></table><p>对多个工具的并发操作，应先区分可独立读取、可独立修改与共同写入同一对象。共享状态的修改保留顺序、版本前提或冲突处理；不可逆动作前重新核验仍有效的权限与停止条件。请求超时表示结果未知，不能直接当作未执行而重复动作；先以请求标识或对象状态核对，再决定是否重试。这里规定的是执行责任，不要求所有应用采用同一种日志格式。</p><p>停止也有自己的完成条件：发出停止、执行器确认、在途动作终止以及已发生后果的补救分别登记。只确认前两步时，准确说明相应范围；若安全撤收需要独立职责下的有限动作，按其自身依据继续，不能因主任务停止而放弃必要接续。修复失败时保留失败对象与现实后果，禁止以一份新的正常输出覆盖它们。</p></div>',1)])])}const I=d(o,[["render",h]]);export{b as __pageData,I as default};
